import { CreateTokenData, createToken, getTokenStatus } from '@proton/shared/lib/api/payments';
import { PAYMENT_TOKEN_STATUS } from '@proton/shared/lib/constants';
import { getHostname } from '@proton/shared/lib/helpers/url';
import { Api } from '@proton/shared/lib/interfaces';

import PaymentVerificationModal from './PaymentVerificationModal';
import {
    AmountAndCurrency,
    CardPayment,
    ExistingPayment,
    PaymentTokenResult,
    TokenPaymentMethod,
    WrappedCardPayment,
    isExistingPayment,
    isTokenPaymentMethod,
} from './interface';
import { toTokenPaymentMethod } from './paymentTokenToParams';

const { STATUS_PENDING, STATUS_CHARGEABLE, STATUS_FAILED, STATUS_CONSUMED, STATUS_NOT_SUPPORTED } =
    PAYMENT_TOKEN_STATUS;

const DELAY_PULLING = 5000;
const DELAY_LISTENING = 1000;

/**
 * Initialize new tab and listen it
 */
export const process = (
    {
        Token,
        api,
        ApprovalURL,
        ReturnHost,
        signal,
    }: Pick<PaymentTokenResult, 'ApprovalURL' | 'ReturnHost' | 'Token'> & {
        api: Api;
        signal: AbortSignal;
    },
    delayListening = DELAY_LISTENING,
    delayPolling = DELAY_PULLING
) => {
    const tab = window.open(ApprovalURL);

    return new Promise<boolean>((resolve, reject) => {
        let settled = false;
        let processing = false;
        let listeningTimer: ReturnType<typeof setTimeout> | undefined;
        let pollingTimer: ReturnType<typeof setTimeout> | undefined;

        const cleanup = () => {
            clearTimeout(listeningTimer);
            clearTimeout(pollingTimer);
            // eslint-disable-next-line @typescript-eslint/no-use-before-define
            window.removeEventListener('message', onMessage, false);
            // eslint-disable-next-line @typescript-eslint/no-use-before-define
            signal.removeEventListener('abort', abort);
            tab?.close();
        };

        const finish = (verified: boolean, error?: Error) => {
            if (settled) {
                return;
            }
            settled = true;
            cleanup();
            if (error) {
                reject(error);
            } else {
                resolve(verified);
            }
        };

        const poll = async () => {
            if (settled || signal.aborted) {
                finish(false);
                return;
            }
            try {
                const { Status } = await api({ ...getTokenStatus(Token), signal });
                if (settled) {
                    return;
                }
                if (Status === STATUS_PENDING) {
                    pollingTimer = setTimeout(poll, delayPolling);
                } else if (
                    Status === STATUS_CHARGEABLE ||
                    Status === STATUS_FAILED ||
                    Status === STATUS_CONSUMED ||
                    Status === STATUS_NOT_SUPPORTED
                ) {
                    finish(Status === STATUS_CHARGEABLE);
                } else {
                    finish(false, new Error(c('Error').t`Unknown payment token status`));
                }
            } catch (error: any) {
                if (signal.aborted) {
                    finish(false);
                } else {
                    finish(false, error);
                }
            }
        };

        const listenTab = () => {
            if (settled) {
                return;
            }
            if (tab?.closed) {
                finish(false);
                return;
            }
            listeningTimer = setTimeout(listenTab, delayListening);
        };

        const onMessage = (event: MessageEvent) => {
            if (settled || processing || getHostname(event.origin) !== ReturnHost) {
                return;
            }

            if (event.data?.cancel === '1') {
                finish(false);
                return;
            }
            processing = true;
            clearTimeout(listeningTimer);
            tab?.close();
            poll();
        };

        const abort = () => {
            finish(false);
        };

        signal.addEventListener('abort', abort);
        window.addEventListener('message', onMessage, false);
        if (signal.aborted) {
            finish(false);
            return;
        }
        listenTab();
    });
};

/**
 * Prepares the parameters and makes the API call to create the payment token.
 *
 * @param params
 * @param api
 * @param amountAndCurrency
 */
